const G=9.8,TG=[30,45,18],N=60;
function arc(a,v){const r=a*Math.PI/180;return{vx:v*Math.cos(r),vy:v*Math.sin(r),T:2*v*Math.sin(r)/G}}
function pos(s,t){return[s.vx*t,1.5+s.vy*t-G*t*t/2,0]}
function pts(a,v,f){const s=arc(a,v),o=[];for(let i=0;i<=40;i++)o.push(pos(s,s.T*f*i/40));return o}
function over(s){return s.hits>=3||s.used>=10}
export function initialState(){return{fly:false,k:0,a:45,v:15,used:0,hits:0,ti:0,last:null,prev:null}}
export function reduce({state,event,inputs}){
if(event.type==='action'&&event.action==='launch'){if(state.fly||over(state))return state;return{...state,fly:true,k:0,a:inputs.angle,v:inputs.speed,prev:state.last}}
if(event.type==='step'&&state.fly){const k=state.k+1;if(k<N)return{...state,k};
const s=arc(state.a,state.v),R=s.vx*s.T,tg=TG[state.ti],m=R-tg,hit=Math.abs(m)<=1.5;
return{...state,fly:false,k:N,used:state.used+1,hits:state.hits+(hit?1:0),ti:Math.min(2,state.ti+(hit?1:0)),last:{a:state.a,v:state.v,R,m,T:s.T,H:s.vy*s.vy/(2*G),hit,tg}}}
return state}
export function evaluate({inputs,state}){
const th=(inputs.angle-90)*Math.PI/180,n={pivot:{quaternion:[0,0,Math.sin(th/2),Math.cos(th/2)]}};
n.target={position:[TG[state.ti],0,0]};
let bp=[0,1.5,0],cur=null;
if(state.fly){const s=arc(state.a,state.v);bp=pos(s,s.T*state.k/N);cur=pts(state.a,state.v,state.k/N)}else if(state.last)cur=pts(state.last.a,state.last.v,1);
n.ball={position:bp};
n.trail=cur?{visible:true,points:cur}:{visible:false,points:[]};
const g=state.prev;n.ghostTrail=g?{visible:true,points:pts(g.a,g.v,1)}:{visible:false,points:[]};
const r={used:state.used,hits:state.hits},L=state.last;
if(L){r.dist=L.R;r.miss=Math.abs(L.m);r.side=L.hit?'hit':(L.m<0?'short':'long');r.ftime=L.T;r.hmax=L.H}
let goal;const left=10-state.used;
if(state.hits>=3)goal={status:'won',message:'You hit all 3 targets in '+state.used+' launches!'};
else if(state.used>=10&&!state.fly)goal={status:'lost',message:'Out of launches: '+state.hits+' of 3 targets hit.'};
else{let msg='Target at '+TG[state.ti]+' m. Launches left: '+left+'.';
if(state.fly)msg='Ball in flight...';else if(L)msg=(L.hit?'Hit! ':'Missed by '+Math.abs(L.m).toFixed(1)+' m ('+(L.m<0?'short':'long')+'). ')+msg;
goal={status:'playing',message:msg}}
return{nodes:n,readouts:r,goal}}
